-- Platform database. Keep this separate from clinical records and shared patient identities.
BEGIN;
SELECT pg_advisory_xact_lock(734251896);
CREATE TABLE IF NOT EXISTS "PlatformAuditEvents" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ActorId" varchar(64) NOT NULL,
    "Action" varchar(80) NOT NULL,
    "TargetId" varchar(64),
    "OccurredAt" timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_platform_audit_time ON "PlatformAuditEvents"("OccurredAt");
INSERT INTO "PlatformSchemaVersions" ("Version") VALUES (4) ON CONFLICT DO NOTHING;
COMMIT;
